var scene=UnityEngine.SceneManagement.SceneManager.GetSceneByPath("Assets/Scenes/Main Game Scene.unity");
if(!scene.IsValid() || !scene.isLoaded) throw new System.Exception("Main scene is not loaded");
if(UnityEditor.EditorApplication.isPlaying) throw new System.Exception("Exit Play Mode first");
var all=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<UnityEngine.Transform>(true)).ToArray();
float[] Vec(UnityEngine.Vector3 v)=>new[]{v.x,v.y,v.z};
object Info(UnityEngine.Transform t) { var rs=t.GetComponentsInChildren<UnityEngine.Renderer>(true); return new {name=t.name,path=UnityEditor.AnimationUtility.CalculateTransformPath(t,null),pos=Vec(t.position),rotation=Vec(t.eulerAngles),scale=Vec(t.lossyScale),renderers=rs.Select(r=>new{name=r.name,center=Vec(r.bounds.center),size=Vec(r.bounds.size),min=Vec(r.bounds.min),max=Vec(r.bounds.max)}).ToArray()}; }
var mm=all.Select(t=>t.GetComponent<MapMagic.Core.MapMagicObject>()).First(x=>x!=null);
var terrains=all.Select(t=>t.GetComponent<UnityEngine.Terrain>()).Where(t=>t!=null).ToArray();
var data=new { scene=scene.path,dirty=scene.isDirty,active=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path,compiling=UnityEditor.EditorApplication.isCompiling,generating=mm.IsGenerating(),mmPosition=Vec(mm.transform.position),graph=UnityEditor.AssetDatabase.GetAssetPath(mm.graph),towers=all.Where(t=>t.name.StartsWith("CablewayTower_") && t.parent!=null && t.parent.name=="索道群").Select(Info).ToArray(),routes=all.Where(t=>t.name.StartsWith("Cable route")).Select(Info).ToArray(),factory=all.Where(t=>t.name=="工厂建筑群").Select(Info).ToArray(),terrains=terrains.Select(t=>new {path=UnityEditor.AnimationUtility.CalculateTransformPath(t.transform,null),active=t.isActiveAndEnabled,pos=Vec(t.transform.position),size=Vec(t.terrainData.size),resolution=t.terrainData.heightmapResolution,data=UnityEditor.AssetDatabase.GetAssetPath(t.terrainData)}).ToArray(),locks=mm.locks.Select(l=>new{name=l.guiName,locked=l.locked,position=new[]{l.worldPos.x,l.worldPos.z}}).ToArray(),imports=mm.graph.GeneratorsOfType<MapMagic.Nodes.MatrixGenerators.Import200>().Select(n=>new{asset=UnityEditor.AssetDatabase.GetAssetPath(n.matrixAsset)}).ToArray()};
System.IO.File.WriteAllText("ArtSource/Cableway/FoothillStationPlacement/survey.json",Newtonsoft.Json.JsonConvert.SerializeObject(data,Newtonsoft.Json.Formatting.Indented));
return new{scene=scene.path,dirty=scene.isDirty,terrainCount=terrains.Length,generating=mm.IsGenerating()};
